"""One loaded model, sequential original/candidate runner correctness comparison."""
import gc, hashlib, importlib.util, json, os, sys, time
from pathlib import Path
root=Path(__file__).parent;sys.path.insert(0,str(root/'original-root'))
import mlx.core as mx
import numpy as np
from tutorial_code.miniengine.engine.llm_engine import LLMEngine
from tutorial_code.miniengine.engine.model_runner import ModelRunner as OriginalRunner
from tutorial_code.miniengine.engine.scheduler import Scheduler
from tutorial_code.miniengine.sampling_params import SamplingParams
from tutorial_code.miniengine.model import layers as original_layers
from tutorial_code.miniengine.model import gdn as original_gdn
from tutorial_code.miniengine.kernels import gdn_metal as original_metal
from resource_snapshot import snapshot, deltas, guard
spec=importlib.util.spec_from_file_location('tutorial_code.miniengine.engine.pipeline_runner',root/'accepted-step12-root/tutorial_code/miniengine/engine/model_runner.py')
module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module);CandidateRunner=module.ModelRunner
def load_extra(name,path):
 spec=importlib.util.spec_from_file_location(name,path);module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module);return module
candidate_layers=load_extra('candidate_layers',root/'accepted-step12-root/tutorial_code/miniengine/model/layers.py')
candidate_metal=load_extra('candidate_metal',root/'accepted-step12-root/tutorial_code/miniengine/kernels/gdn_metal.py')
candidate_gdn=load_extra('tutorial_code.miniengine.model.candidate_gdn',root/'accepted-step12-root/tutorial_code/miniengine/model/gdn.py')
original_functions=(original_layers.RMSNorm.__call__,original_layers.GatedRMSNorm.__call__,original_metal.gated_delta_step_metal,original_gdn.GatedDeltaNet._decode)
w=json.loads((root/'workload.json').read_text());resources=[]
def probe(label):
 resources.append(snapshot(label,os.getpid()));deltas(resources)
 (root/'correctness-accepted-step12-resources.json').write_text(json.dumps(resources,indent=2));guard(resources)
probe('before-model-launch')
loaded=LLMEngine(w['model_dir'],max_seqs=4,max_len=2048,dtype=mx.bfloat16)
model=loaded.model;mx.synchronize();mx.clear_cache();probe('model-ready')
from functools import partial
for layer in model.layers:
 if not layer.is_attn and hasattr(candidate_gdn, '_decode_prework'):
  net=layer.linear_attn;net._compiled_prework=mx.compile(partial(candidate_gdn._decode_prework,Hk=net.Hk,Hv=net.Hv,Dk=net.Dk,Dv=net.Dv))
def hash_arrays(arrays):
 h=hashlib.sha256()
 for array in arrays:
  value=np.asarray(array.astype(mx.float32));h.update(str(value.shape).encode());h.update(value.tobytes())
 return h.hexdigest()
class RecordingModel:
 def __init__(self):self.calls=[]
 def __getattr__(self,name):return getattr(model,name)
 def __call__(self,ids,ctx,**kwargs):
  lg=model(ids,ctx,**kwargs);self.calls.append((ctx.mode,lg));return lg
def make_engine(runner_type):
 e=LLMEngine.__new__(LLMEngine);e.model=model;e.cfg=loaded.cfg;e.eos_ids=loaded.eos_ids
 e.scheduler=Scheduler(4,2048,512,e.eos_ids);e.requests={};e._counter=0
 rec=RecordingModel();e.runner=runner_type(rec,2048);return e,rec
def exercise(kind,runner_type):
 if runner_type is CandidateRunner:
  original_layers.RMSNorm.__call__=candidate_layers.RMSNorm.__call__
  original_layers.GatedRMSNorm.__call__=candidate_layers.GatedRMSNorm.__call__
  original_metal.gated_delta_step_metal=candidate_metal.gated_delta_step_metal
  original_gdn.GatedDeltaNet._decode=candidate_gdn.GatedDeltaNet._decode
 else:
  original_layers.RMSNorm.__call__,original_layers.GatedRMSNorm.__call__,original_metal.gated_delta_step_metal,original_gdn.GatedDeltaNet._decode=original_functions
 mx.random.seed(413)
 e,rec=make_engine(runner_type);outputs={};states=[];steps=0
 def add(name,prompt,cap=32,stop=()):
  e.add_request(prompt,SamplingParams(max_tokens=cap,temperature=0,ignore_eos=False,stop_token_ids=stop),req_id=name);outputs[name]=[]
 if kind=='fixed33':add('one',w['prompt_ids'],33)
 elif kind=='normal-eos':add('one',w['prompt_ids'],128)
 elif kind=='cross-cache-boundary':add('long',w['prompt_ids']*14,32)
 elif kind=='mixed-lifecycle':
  add('short',w['prompt_ids'],4);add('long',w['prompt_ids'],32);add('stop',w['prompt_ids'],32,(w['continuation_ids'][5],))
 elif kind=='late-chunked-prefill':
  e.scheduler.max_batched_tokens=64;add('existing',w['prompt_ids'],32)
 elif kind in ('mutable-sampling','input-mutation'):add('one',w['prompt_ids'],12)
 while e.has_work():
  produced=e.step();steps+=1
  for rid,t,done in produced:outputs[rid].append(t)
  if e.runner.batch.size and (kind=='fixed33' or steps in (2,4,8,16,24)):
   mx.eval(*e.runner.batch.arrays());states.append({'step':steps,'req_ids':list(e.runner.batch.req_ids),'lens':list(e.runner.batch.lens),'hash':hash_arrays(e.runner.batch.arrays())})
  if kind=='mixed-lifecycle' and steps==3:add('late',w['prompt_ids'],7)
  if kind=='late-chunked-prefill' and steps==3:add('late',w['prompt_ids']*14,7)
  if kind=='mutable-sampling' and steps==3:
   p=e.requests['one'].sampling;p.temperature=.7;p.top_k=20;p.top_p=.85
  if kind=='mutable-sampling' and steps==7 and 'one' in e.requests:
   p=e.requests['one'].sampling;p.temperature=0;p.top_k=0;p.top_p=1
  if kind=='input-mutation' and steps==3:e.requests['one'].output_token_ids[-1]=w['continuation_ids'][10]
 assert not e.requests and not e.runner.staging and e.runner.batch.size==0
 assert getattr(e.runner,'_ahead',None) is None
 # Reuse after complete unload is part of the same request lifecycle check.
 add('reuse',w['prompt_ids'],5)
 while e.has_work():
  for rid,t,_ in e.step():outputs[rid].append(t)
 mx.synchronize()
 calls=[{'mode':mode,'shape':list(lg.shape),'hash':hash_arrays([lg]),'argmax':mx.argmax(lg,axis=-1).tolist()} for mode,lg in rec.calls]
 del e,rec;gc.collect();mx.clear_cache()
 return {'outputs':outputs,'states':states,'calls':calls,'steps':steps}
results=[]
for kind in ['fixed33','normal-eos','mixed-lifecycle','cross-cache-boundary','late-chunked-prefill','mutable-sampling','input-mutation']:
 before=exercise(kind,OriginalRunner);after=exercise(kind,CandidateRunner)
 (root/'correctness-accepted-step12-latest-case.json').write_text(json.dumps({'case':kind,'before':before,'after':after},indent=2))
 assert before['outputs']==after['outputs'],(kind,'output mismatch')
 assert before['states']==after['states'],(kind,'cache mismatch')
 # An EOS or admission can discard a correctly computed future; compare fixed33
 # uninterrupted arithmetic exactly and report extra calls in other scenarios.
 if kind=='fixed33':assert before['calls']==after['calls'],(kind,'logit mismatch')
 results.append({'case':kind,'output_ids_equal':True,'committed_cache_hashes_equal':True,'all_fixed33_logit_vectors_bitexact':kind=='fixed33','before':before,'after':after})
 (root/'correctness-accepted-step12.json').write_text(json.dumps({'passed':True,'scope':'same loaded weights, normal greedy outputs, exact committed cache hashes, uninterrupted33 vectors; adversarial mixed admissions/stops,267-token prompt crosses256 cache boundary','cases':results},indent=2))
 probe('after-'+kind);print('passed',kind,len(before['calls']),len(after['calls']),flush=True)
probe('after-correctness-before-unload')
